class Solution {
public:
    int mctFromLeafValues(vector<int>& arr) {
        vector<int> st;
        st.push_back(INT_MAX);
        int res = 0;
        for (int x : arr) {
            while (st.back() <= x) {
                int mid = st.back();
                st.pop_back();
                res += mid * min(st.back(), x);
            }
            st.push_back(x);
        }
        while (st.size() > 2) {
            int top = st.back();
            st.pop_back();
            res += top * st.back();
        }
        return res;
    }
};
